def load_text(path: Path) -> str:
    raw = path.read_bytes()
    if raw.startswith(b"\xff\xfe") or raw.startswith(b"\xfe\xff"):
        u16 = raw.decode("utf-16", errors="replace")
        u8 = raw.decode("utf-8", errors="ignore")
        return u16 + "\n" + u8
    return raw.decode("utf-8", errors="replace")
